{
  "items": [
    {
      "name": "FormalMultilinearSeries.norm_apply_eq_norm_coef",
      "module_name": "Mathlib.Analysis.Calculus.FormalMultilinearSeries",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u} {E : Type v} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {p : FormalMultilinearSeries 𝕜 𝕜 E} {n : ℕ}, ‖p n‖ = ‖p.coeff n‖"
    },
    {
      "name": "ModularFormClass.qExpansionFormalMultilinearSeries_apply_norm",
      "module_name": "Mathlib.NumberTheory.ModularForms.QExpansion",
      "kind": "theorem",
      "type": "∀ {F : Type u_1} [inst : FunLike F UpperHalfPlane ℂ] {h : ℝ} (f : F) (m : ℕ),\n  ‖ModularFormClass.qExpansionFormalMultilinearSeries h f m‖ = ‖(PowerSeries.coeff m) (ModularFormClass.qExpansion h f)‖"
    },
    {
      "name": "MonomialOrder.leadingCoeff_monomial",
      "module_name": "Mathlib.RingTheory.MvPolynomial.MonomialOrder",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [inst : CommSemiring R] {d : σ →₀ ℕ} (c : R),\n  m.leadingCoeff ((MvPolynomial.monomial d) c) = c"
    },
    {
      "name": "PowerSeries.coeff_monomial_same",
      "module_name": "Mathlib.RingTheory.PowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (n : ℕ) (a : R), (PowerSeries.coeff n) ((PowerSeries.monomial n) a) = a"
    },
    {
      "name": "MvPolynomial.coeffAddMonoidHom_apply",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (m : σ →₀ ℕ) (p : MvPolynomial σ R),\n  (MvPolynomial.coeffAddMonoidHom m) p = MvPolynomial.coeff m p"
    },
    {
      "name": "MvPolynomial.coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → (σ →₀ ℕ) → MvPolynomial σ R → R"
    },
    {
      "name": "MvPowerSeries.coeff_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [inst_1 : DecidableEq σ] (m n : σ →₀ ℕ) (a : R),\n  (MvPowerSeries.coeff m) ((MvPowerSeries.monomial n) a) = if m = n then a else 0"
    },
    {
      "name": "MvPowerSeries.coeff_monomial_same",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (n : σ →₀ ℕ) (a : R),\n  (MvPowerSeries.coeff n) ((MvPowerSeries.monomial n) a) = a"
    }
  ]
}
